{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C37"],
      "claim": "Posaconazole, the highest-transfer analogue (0.9549), has measured absolute oral bioavailability around 50% in healthy volunteers, directly supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Vilazodone (transfer 0.9497) has absolute oral bioavailability of 72% with food in healthy volunteers, well above the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Ivosidenib (transfer 0.9448) has absolute oral bioavailability of 57.2% in healthy subjects under fasting conditions, based on direct IV comparison.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Tazemetostat (transfer 0.9326) has mean absolute bioavailability of 33.9% in patients, the lowest among high-transfer analogues but still above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Sertindole (transfer 0.9326) has oral bioavailability of about 75% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Abemaciclib (transfer 0.9293) has absolute oral bioavailability of 45% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C56"],
      "claim": "Tepotinib (transfer 0.9287) has absolute oral bioavailability of 72% in healthy volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C69"],
      "claim": "DPP-4 inhibitor analogues (transfer 0.9282) are well absorbed orally with bioavailability of 75–87% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Aprepitant (transfer 0.9268), despite BCS IV classification, has absolute bioavailability of 59% (95% CI 53–65%) for 125 mg capsules, showing that unfavorable solubility/permeability predictions do not preclude high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Paliperidone (transfer 0.9253) has absolute oral bioavailability of 28% for ER tablets, the lowest measured among analogues but still above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All ten high-transfer analogues have measured absolute oral bioavailability between 28% and 87% in humans, consistently above the 20% threshold; the lowest measured value (paliperidone 28%) still supports high. The mixed/unclear physicochemical prior is outweighed by direct human absolute bioavailability data from structurally and pharmacokinetically relevant analogues.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement for the query molecule.",
    "Formulation, food effects, and transporter-mediated absorption are not directly assessed for the query.",
    "High molecular weight, TPSA, and ionization may affect permeability, but analogues with similar properties still show F >20%."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

